/**
 * A lanterna do vaga-lume — porte de `componentes/viz/vaga_lume.js`.
 *
 * O vaga-lume Photuris produz luz fria — quase toda a energia vira luz, e não
 * calor. Só que produzir não basta: a luz precisa SAIR. A superfície da lanterna
 * é coberta de escamas inclinadas que quebram a reflexão interna, e existe uma
 * inclinação que deixa escapar o máximo. Engenheiros copiaram isso para melhorar
 * LEDs.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const vagaLume: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const inclinacao = numeroDe(valores, 'inc', 0);
    const luz = numeroDe(info, 'luz', 0);
    const ok = info.ok === true;
    const brilho = Math.max(0, (luz - 35) / 65);

    titulo(ctx, L, A, 'Luz fria — e como fazê-la sair');

    const cx = L * 0.44;
    const cy = A * 0.58;

    // **A escala.** Os tamanhos eram todos literais em pixels — o bicho ficava
    // do mesmo tamanho num telefone e num monitor, e no telefone era uma
    // manchinha no meio de um quadro vazio. Agora tudo sai daqui.
    const E = limitar(Math.min(L * 0.075, A * 0.11), 14, 34);

    // O halo cresce com o que de fato escapa.
    const raio = E * (2.4 + brilho * 3);
    const halo = ctx.createRadialGradient(cx, cy, E * 0.2, cx, cy, raio);
    halo.addColorStop(0, `rgb(176 125 16 / ${(0.2 + 0.5 * brilho) * 100}%)`);
    halo.addColorStop(1, 'rgb(176 125 16 / 0%)');
    ctx.fillStyle = halo;
    ctx.beginPath();
    ctx.arc(cx, cy, raio, 0, Math.PI * 2);
    ctx.fill();

    // As pernas, antes do corpo, para saírem por baixo dele.
    ctx.strokeStyle = '#2b2b20';
    ctx.lineWidth = Math.max(1.6, E * 0.09);
    ctx.lineCap = 'round';
    for (const lado of [-1, 1]) {
      for (let i = 0; i < 3; i++) {
        ctx.beginPath();
        ctx.moveTo(cx - E * (1.9 - i * 0.5), cy + lado * E * 0.3);
        ctx.lineTo(cx - E * (2.3 - i * 0.55), cy + lado * E * 0.95);
        ctx.lineTo(cx - E * (1.8 - i * 0.55), cy + lado * E * 1.35);
        ctx.stroke();
      }
    }

    // As antenas, serrilhadas como as do vaga-lume de verdade.
    for (const lado of [-1, 1]) {
      ctx.beginPath();
      ctx.moveTo(cx - E * 2.3, cy + lado * E * 0.15);
      ctx.quadraticCurveTo(cx - E * 3.2, cy + lado * E * 0.9, cx - E * 3.9, cy + lado * E * 0.6);
      ctx.stroke();
    }

    // O corpo: cabeça e pronoto escuros, e a lanterna acesa no abdômen.
    ctx.fillStyle = '#3a3a2c';
    ctx.beginPath();
    ctx.ellipse(cx - E * 2.15, cy, E * 0.5, E * 0.42, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#c2662f';
    ctx.beginPath();
    ctx.ellipse(cx - E * 1.45, cy, E * 0.62, E * 0.52, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = `rgb(200 165 40 / ${(0.5 + 0.45 * brilho) * 100}%)`;
    ctx.beginPath();
    ctx.ellipse(cx + E * 0.1, cy, E * 1.55, E * 0.95, 0, 0, Math.PI * 2);
    ctx.fill();

    // Os élitros: as duas asas duras fechadas por cima do abdômen.
    ctx.fillStyle = 'rgb(58 58 44 / 82%)';
    for (const lado of [-1, 1]) {
      ctx.beginPath();
      ctx.ellipse(
        cx - E * 0.15,
        cy + lado * E * 0.4,
        E * 1.35,
        E * 0.44,
        lado * 0.07,
        0,
        Math.PI * 2,
      );
      ctx.fill();
    }
    ctx.strokeStyle = '#2b2b20';
    ctx.lineWidth = Math.max(1, E * 0.05);
    ctx.beginPath();
    ctx.moveTo(cx - E * 1.4, cy);
    ctx.lineTo(cx + E * 1.15, cy);
    ctx.stroke();

    // As escamas, no ângulo do controle. Traço escuro por baixo para elas não se
    // perderem contra o halo.
    const angulo = (inclinacao / 100) * Math.PI * 0.5;
    const comprimento = E;
    for (let i = -3; i <= 3; i++) {
      const sx = cx + E * 0.1 + i * E * 0.5;
      const sy = cy - E * 0.9;
      const ex = sx + Math.cos(Math.PI / 2 - angulo) * comprimento;
      const ey = sy - Math.sin(Math.PI / 2 - angulo) * comprimento;

      ctx.strokeStyle = cor.texto;
      ctx.lineWidth = E * 0.28;
      ctx.beginPath();
      ctx.moveTo(sx, sy);
      ctx.lineTo(ex, ey);
      ctx.stroke();

      ctx.strokeStyle = cor.ouro;
      ctx.lineWidth = E * 0.15;
      ctx.beginPath();
      ctx.moveTo(sx, sy);
      ctx.lineTo(ex, ey);
      ctx.stroke();
    }

    // Os raios que escapam — e, quando a inclinação é ruim, os que voltam presos.
    const escapam = Math.round(luz / 11);
    ctx.strokeStyle = cor.ouro;
    ctx.globalAlpha = 0.4 + 0.5 * brilho;
    ctx.lineWidth = Math.max(1.4, E * 0.09);
    for (let i = 0; i < escapam; i++) {
      const rx = cx - E * 1.2 + i * E * 0.38;
      ctx.beginPath();
      ctx.moveTo(rx, cy - E * 0.9);
      ctx.lineTo(rx + (i - escapam / 2) * E * 0.12, cy - E * (2.5 + ((t * 1.4) % 0.8)));
      ctx.stroke();
    }
    ctx.globalAlpha = 1;

    if (!ok) {
      ctx.strokeStyle = cor.fraco;
      ctx.lineWidth = Math.max(1.4, E * 0.09);
      for (let i = 0; i < 3; i++) {
        const rx = cx - E * 0.5 + i * E * 0.5;
        ctx.beginPath();
        ctx.moveTo(rx, cy - E * 0.75);
        ctx.lineTo(rx + E * 0.25, cy + E * 0.25);
        ctx.stroke();
      }
    }

    // A barra de brilho.
    const gx = L - 14;
    const gy = A * 0.18;
    const gh = A * 0.62;
    retangulo(ctx, gx, gy, 9, gh, 4, cor.trilho);
    const cheia = (gh * limitar(luz, 0, 100)) / 100;
    retangulo(ctx, gx, gy + gh - cheia, 9, cheia, 4, ok ? cor.verde : cor.ouro);

    texto(
      ctx,
      `inclinação ${Math.round(inclinacao)}° · brilho ${Math.round(luz)}%`,
      L / 2,
      A * 0.95,
      limitar(A * 0.044, 10, 14),
      { cor: ok ? cor.verde : cor.fraco, peso: 700 },
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default vagaLume;
